<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\DTO\Exam\ExamParticipationDTO; use Inc\Repositories\WPDBRepositories\ExamParticipationRepository; use Inc\Repositories\WPDBRepositories\ExamParticipantRepository; class ExamParticipationService { private ExamParticipationRepository $participationRepo; private ExamParticipantRepository $participantRepo; public function __construct( ?ExamParticipationRepository $pRepo = null, ?ExamParticipantRepository $partRepo = null ) { $this->participationRepo = $pRepo ?? new ExamParticipationRepository(); $this->participantRepo = $partRepo ?? new ExamParticipantRepository(); } public function registerParticipant( int $eventId, int $participantId, string $audience ): int { return $this->participationRepo->insert( [ 'event_id' => $eventId, 'participant_id' => $participantId, 'audience' => $audience, 'created_at' => current_time( 'mysql', true ), 'updated_at' => current_time( 'mysql', true ), ] ); } public function getParticipation( int $participationId ): ?ExamParticipationDTO { return $this->participationRepo->find( $participationId ); } public function findByEventAndParticipant( int $eventId, int $participantId ): ?ExamParticipationDTO { return $this->participationRepo->findByEventAndParticipant( $eventId, $participantId ); } public function getEventParticipations( int $eventId ): array { return $this->participationRepo->findByEvent( $eventId ); } public function admitParticipant( int $participationId, int $admittedByUserId ): bool { return $this->participationRepo->update( $participationId, [ 'admitted_at' => current_time( 'mysql', true ), 'admitted_by_user_id' => $admittedByUserId, 'updated_at' => current_time( 'mysql', true ), ] ); } public function allowTransfer( int $participationId ): bool { return $this->participationRepo->update( $participationId, [ 'transfer_allowed' => true, 'updated_at' => current_time( 'mysql', true ), ] ); } }
